<?php
$q = mysqli_query($koneksi, "SELECT p.*, pm.namapeminjam, pm.kelas, COUNT(d.iddetilpeminjaman) AS jumlahitem, COALESCE(SUM(d.jumlahpinjam),0) AS totalunit FROM peminjaman p JOIN peminjam pm ON pm.idpeminjam=p.idpeminjam LEFT JOIN detilpeminjaman d ON d.idpeminjaman=p.idpeminjaman WHERE p.status='Dipinjam' GROUP BY p.idpeminjaman ORDER BY p.idpeminjaman DESC");
?>
<div class="page-heading"><div><span class="eyebrow">TRANSAKSI</span><h1>Daftar Barang Belum Dikembalikan</h1><p>Halaman ini menampilkan peminjaman yang masih aktif dan barangnya belum dikembalikan. Pilih detail untuk memproses pengembalian.</p></div><a class="btn btn-primary" href="index.php?halaman=createpengembalian"><i class="fas fa-undo mr-1"></i> Proses Pengembalian</a></div>
<div class="card modern-card"><div class="card-body p-0"><div class="table-responsive"><table class="table modern-table mb-0"><thead><tr><th>ID Peminjaman</th><th>Peminjam</th><th>Kelas</th><th>Tanggal Pinjam</th><th>Jenis Alat</th><th>Total Unit</th><th>Batas Kembali</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
<?php if (!$q || mysqli_num_rows($q)===0): ?><tr><td colspan="9" class="text-center text-muted p-4">Tidak ada barang yang sedang dipinjam. Semua pengembalian sudah selesai.</td></tr><?php else: while($r=mysqli_fetch_assoc($q)): ?><tr><td>#<?=(int)$r['idpeminjaman']?></td><td><strong><?=htmlspecialchars($r['namapeminjam'])?></strong></td><td><?=htmlspecialchars($r['kelas']??'-')?></td><td><?=function_exists('tanggalIndonesia')?tanggalIndonesia($r['tanggalpinjam']):htmlspecialchars($r['tanggalpinjam'])?></td><td><?=(int)$r['jumlahitem']?> jenis</td><td><?=(int)$r['totalunit']?> unit</td><td><?=!empty($r['tanggalrencana'])?(function_exists('tanggalIndonesia')?tanggalIndonesia($r['tanggalrencana']):htmlspecialchars($r['tanggalrencana'])):'-'?></td><td><span class="status-badge status-warning">Belum Dikembalikan</span></td><td><a class="btn btn-sm btn-primary" href="index.php?halaman=showpengembalian&id=<?=(int)$r['idpeminjaman']?>"><i class="fas fa-undo mr-1"></i> Proses Pengembalian</a></td></tr><?php endwhile; endif; ?>
</tbody></table></div></div></div>
